// Hand-written `ioredis` stub for the flowatlas fixture suite. It declares only
// what `fixtures/nest-redis-pubsub/src` touches, in the real library's shape.
//
// This stub is the pub/sub half of `ioredis` and is intentionally a different
// file from the one in `fixtures/nest-leaves`, which declares the key/value half
// for the cache adapter: each fixture stubs exactly the surface it uses.
//
// `on('message', ...)` is overloaded so that the listener's parameters are typed
// on the pub/sub event and untyped elsewhere, which is what the real library
// does and what makes the delegating-arrow row readable.

export type MessageListener = (channel: string, message: string) => void;
export type PatternMessageListener = (pattern: string, channel: string, message: string) => void;

export interface RedisOptions {
  host?: string;
  port?: number;
  db?: number;
  lazyConnect?: boolean;
}

export declare class Redis {
  constructor(options?: RedisOptions);

  publish(channel: string, message: string): Promise<number>;
  subscribe(...channels: string[]): Promise<number>;
  psubscribe(...patterns: string[]): Promise<number>;
  unsubscribe(...channels: string[]): Promise<number>;

  on(event: 'message', listener: MessageListener): this;
  on(event: 'pmessage', listener: PatternMessageListener): this;
  on(event: string, listener: (...args: any[]) => void): this;

  duplicate(): Redis;
  quit(): Promise<'OK'>;
}

export default Redis;
